 "value": ["qty", "uom"]}, {"label": "Balance", "value": ["balance"]}, {"label": "Name and license number of the prescribing physician", "value": ["authority_issuer", "authority_issuer_licence"], "when": "Out"}, {"label": "Name and license number of the dispensing pharmacist", "value": ["dispenser_name", "dispenser_licence"], "when": "Out"}, {"label": "Patient's name and address", "value": ["counterparty", "counterparty_address"], "when": "Out"}, {"label": "Patient identifier (s. 7.2.1)", "value": ["detail_2"], "when": "Out"}, {"label": "Date issued", "value": ["movement_date"], "when": "Out"}, {"label": "Source of the medicine", "value": ["counterparty"], "when": "In"}, {"label": "Receiving date", "value": ["movement_date"], "when": "In"}, {"label": "Invoice reference number", "value": ["reference_no"], "when": "In"}], "groups": false, "correction_words": "an error is re-entered on the next line, the original unmarked", "prints_remarks": false, "medium_note": "Issued by DOH against a fee (DOH Standard s. 3.6): print into it. Each entry contemporaneous and in date order (s. 7.2); the register's stock must match the physical stock (s. 7.5)."} -%}
{%- set data = ivn_register_print(doc) if doc.book == book.ref else {} -%}
<style>
@page { size: A4 landscape; }
/* on screen, the landscape page's width (the core's print view is portrait unless told) */
@media screen { .print-format { max-width: 11.69in; padding: 0.2in; } }
.rsr { font-family: Arial, sans-serif; font-size: 9pt; color: #111; }
.rsr h1 { font-size: 13pt; margin: 0; }
.rsr .sub { color: #444; margin: 2px 0 6px; }
.rsr .notice { border: 1px solid #b26b00; color: #7a4a00; padding: 3px 6px; margin: 4px 0 8px; }
.rsr table { width: 100%; border-collapse: collapse; }
.rsr th, .rsr td { border: 1px solid #555; padding: 3px 4px; vertical-align: top; text-align: start; }
.rsr th { background: #eee; font-weight: bold; }
.rsr td.no { color: #555; white-space: nowrap; }
.rsr td.mark { min-width: 70px; }
.rsr tr.struck td.cell { text-decoration: line-through; }
.rsr tr.note td { font-style: italic; background: #fafafa; }
.rsr tr.blank td { height: 1.4em; }
.rsr .fine { color: #555; font-size: 8pt; }
.rsr .warn { color: #8a1c1c; font-weight: bold; }
.rsr .page { page-break-after: always; }
.rsr .page:last-child { page-break-after: auto; }
.rsr .seal { display: inline-block; width: 30mm; height: 20mm; border: 1px dashed #555; vertical-align: middle; }
</style>
{%- macro value(l, k) -%}
{%- if k == "balance_before" -%}{{ l.balance_before_text or "" }}
{%- elif k == "balance" -%}{{ l.balance_text or "" }}
{%- elif k == "qty" -%}{{ l.qty_text or "" }}
{%- elif k == "counterparty_address" -%}{{ (l.address_lines or [])|join(", ") }}
{%- elif l[k] is defined and l[k] is not none -%}{{ l[k] }}
{%- endif -%}
{%- endmacro -%}
{%- set official = data.book and data.book.medium == "official_book" -%}
{%- set span = book.columns|length + (2 if official else 1) -%}
<div class="rsr" dir="{{ 'rtl' if is_rtl() else 'ltr' }}">
{%- if doc.book != book.ref -%}
<p>This layout prints the {{ book.title|e }}; this period is of {{ doc.book|e }}. Choose that book's print format.</p>
{%- elif not data.book -%}
<p>{{ _("No register book named {0} exists.").format(doc.book)|e }}</p>
{%- else -%}
{%- for page in data.pages -%}
<div class="page">
<h1>{{ book.title|e }}{% if book.form %} <span class="fine">({{ book.form|e }})</span>{% endif %}</h1>
<div class="sub">
{%- if doc.establishment %}{{ doc.establishment|e }}{% for a in (doc.establishment_address or "").split("\n") if a.strip() %}, {{ a|e }}{% endfor %} · {% endif -%}
{{ doc.register_store|e }}{% if page.item_name %} · {{ page.item_name|e }}{% endif %} · {{ data["from"]|e }} – {{ data["to"]|e }}
</div>
{%- if official %}<div class="sub"><strong>{{ (page.place or _("Not placed in the regulator's book: set its first page with Official book page."))|e }}</strong>{% if page.brought_items %} · {{ _("Balance brought forward: {0}.").format(page.brought_items|map("join", " ")|join(" · "))|e }}{% endif %}</div>{% endif %}
<div class="fine">{{ book.data_set_title|e }}. {{ book.cite|e }}</div>
{%- if not book.certified %}<div class="notice">{{ book.notice|e }}</div>{% endif %}
<table>
<thead>
{%- if book.groups %}
<tr><th></th>{% if official %}<th></th>{% endif %}
{%- for c in book.columns -%}
{%- if loop.first or (c.group or "") != (loop.previtem.group or "") -%}
{%- set run = namespace(n=0, on=true) -%}
{%- for d in book.columns[loop.index0:] if run.on -%}{%- if (d.group or "") == (c.group or "") -%}{%- set run.n = run.n + 1 -%}{%- else -%}{%- set run.on = false -%}{%- endif -%}{%- endfor -%}
<th colspan="{{ run.n }}">{{ (c.group or "")|e }}</th>
{%- endif -%}
{%- endfor -%}
</tr>
{%- endif %}
<tr><th>{{ _("No.")|e }}</th>{% if official %}<th>{{ _("Line in the book")|e }}</th>{% endif %}{% for c in book.columns %}<th>{{ c.label|e }}</th>{% endfor %}</tr>
</thead>
<tbody>
{%- if page.brought is not none %}<tr class="note"><td></td><td colspan="{{ span - 1 }}">{{ _("Balance brought forward: {0}.").format(page.brought_text)|e }}</td></tr>{% endif -%}
{%- for r in page.rows -%}
{%- set l = r.line -%}
{%- if r.kind == "blank" -%}
<tr class="blank"><td class="no"></td><td class="no">{{ r.place_line }}</td><td colspan="{{ span - 2 }}"></td></tr>
{%- elif r.kind == "note" -%}
<tr class="note"><td class="no">{{ l.number }}</td>{% if official %}<td class="no">{{ r.place_line or "" }}</td>{% endif %}<td colspan="{{ book.columns|length }}">{{ r.text|e }}</td></tr>
{%- else -%}
<tr{% if r.struck %} class="struck"{% endif %}>
<td class="no">{{ l.number }}{% if l.kind not in ("Sale", "Receipt") %}<br><span class="fine">{{ _(l.kind, context="register entry")|e }}</span>{% endif %}</td>
{%- if official %}<td class="no">{{ r.place_line or "" }}</td>{% endif -%}
{%- for c in book.columns -%}
{%- set cell = namespace(s="") -%}
{%- if not c.when or c.when == l.direction -%}
{%- for k in c.value -%}
{%- set v = value(l, k) -%}
{%- if v != "" -%}{%- set cell.s = cell.s ~ (" · " if cell.s else "") ~ v -%}{%- endif -%}
{%- endfor -%}
{%- endif -%}
<td class="cell{% if c.mark %} mark{% endif %}"{% if book.in_colour and c.when == "In" and l.direction == "In" and l.kind not in ("Opening", "Count") %} style="color: {{ book.in_colour }}"{% endif %}>{{ cell.s|e }}
{%- if loop.last and l.booked_late and not book.prints_remarks %} <span class="fine">{{ _("Entered late.")|e }} {{ l.entered_at|e }}</span>{% endif -%}
{%- if loop.last and l.erased %} <span class="fine">{{ _("A person's details erased after the retention.")|e }}</span>{% endif -%}
{%- if loop.last and r.note %} {{ r.note|e }}{% endif -%}
</td>
{%- endfor -%}
</tr>
{%- endif -%}
{%- else -%}
<tr><td colspan="{{ span }}">{{ (_("No entries in this period.") if data.signed and (page.brought is not none or not data.total) else _("No entries you may read in this period. A print sent by e-mail, in the background or through a shared link reads none: print it signed in."))|e }}</td></tr>
{%- endfor -%}
</tbody>
</table>
</div>
{%- endfor -%}
<p class="fine">{{ (_("{0} entries.").format(data.count) if data.total is none or data.count >= data.total else _("This print holds {0} of the {1} entries in this period: it is not the whole book.").format(data.count, data.total))|e }}
{%- if data.cut %} <span class="warn">{{ _("This print stopped at its reading limit: print a shorter date range.")|e }}</span>{% endif -%}
{%- if data.items_cut %} <span class="warn">{{ _("This print stopped at 2,000 items: the items after them are not printed.")|e }}</span>{% endif -%}
{%- if data.brought_cut %} <span class="warn">{{ _("This print's balances brought forward stop at 2,000 items: every entry is printed, but the items after them show no balance brought forward.")|e }}</span>{% endif -%}
{%- if data.persons_hidden %} <span class="warn">{{ _("A person's details are not shown: your role may not read them.")|e }}</span>{% endif %}
{{ _("Retention: {0} years. Each entry is kept whole that long after its period ends (after its entry, in a book without periods); then a person's details may be erased from it, never the entry.").format(data.book.retention_years)|e }}
{{ (book.correction_words[:1]|upper ~ book.correction_words[1:])|e }}. {{ book.medium_note|e }}</p>
{%- if doc.chain_status %}<p class="fine">{{ _("Entry chain: {0}").format(doc.chain_status)|e }}</p>{% endif %}
{%- if data.book.medium_words %}<p class="fine">{{ data.book.medium_words|e }}</p>{% endif %}
{%- if data.book.medium in ("printed_book", "official_book") %}<p class="fine">{{ _("Kept as the book: signed ____________________ date __________")|e }}</p>{% endif %}
{%- if data.closing %}
{%- if data.sealed %}<p class="fine">{{ _("Sealed at sign-off")|e }}: {{ data.sealed|join(" · ")|e }}</p>{% endif %}
<p class="fine">{% if data.signed_off %}{{ data.signed_off|e }} {% endif %}{{ _("The period's close: signed ____________________ countersigned ____________________")|e }} {{ _("Seal")|e }} <span class="seal"></span></p>
{%- endif %}
{%- endif -%}
</div>

